  vanguard:{view:"globe",body:"luna",title:"Taking the Vanguard",sub:"Darrow and Sevro are fired onto the Vanguard’s bridge above Luna"},
  lunasiege:{view:"site",site:"hyperion",title:"The Siege of Luna",sub:"The Jackal’s hidden bombs go off across Luna"},
  newsovereign:{view:"site",site:"hyperion",title:"A New Sovereign",sub:"Mustang becomes Sovereign of the Rising"},
  galaduel:{view:"site",site:"gala",title:"The Duel at the Gala",sub:"Darrow and Cassius fight to the death before the Sovereign"},
  paxtaking:{view:"site",site:"vanguard",title:"Taking the Vanguard",sub:"Darrow and Sevro breach the bridge; the crew rises; she becomes the Pax"},
  docktrap:{view:"site",site:"ganymede",title:"Trap at Ganymede",sub:"The raid on the defense platform turns into an ambush"},
  yardsburn:{view:"site",site:"ganymede",title:"The Shipyards Burn",sub:"On Darrow’s order, the captured Colossus turns its guns on the dock ring"},
