POIS.mercury=[
 {id:"heliopolis",name:"Heliopolis",lat:HL.heliopolis[0],lon:HL.heliopolis[1],site:"heliopolis",desc:{1:"Second jewel of Mercury, south of the Hesperides and east of the Bay of Sirens: the Hippodrome, the Water Plaza, the Graveyard of Tyrants, and the Mound of Votum on the bay.",5:"Second jewel of Mercury, south of the Hesperides and east of the Bay of Sirens: the Hippodrome, the Water Plaza, the Graveyard of Tyrants, and the Mound of Votum on the bay. It falls in Dark Age."}},
 {id:"tyche",name:"Tyche",lat:HL.tyche[0],lon:HL.tyche[1],site:"tyche",desc:{1:"Mercury’s capital and richest city, on the Sycorax Sea: glass-and-limestone towers of House Votum, libraries carved into the mountains as colossal heads, and bridged islands.",4:"Mercury’s capital and richest city, on the Sycorax Sea: glass-and-limestone towers of House Votum, libraries carved into the mountains as colossal heads, and bridged islands. Darrow’s headquarters.",5:"Mercury’s capital and richest city, on the Sycorax Sea: glass-and-limestone towers of House Votum, libraries carved into the mountains as colossal heads, and bridged islands. Darrow’s headquarters, drowned in Dark Age."}},
 {id:"ladon",name:"Waste of Ladon",lat:HL.ladon[0],lon:HL.ladon[1],site:"ladon",desc:{1:"The chalk desert along Helios’s equator, called the Waste and the Eater of Armies.",5:"The chalk desert along Helios’s equator, called the Waste and the Eater of Armies. In Dark Age the Storm Gods raise a sandstorm across it that swallows armies."}},
 {id:"redreach",name:"Red Reach",from:5,lat:HL.redreach[0],lon:HL.redreach[1],site:"siege",desc:"A Republic military base east of Tyche, one of the few with its own power. In Dark Age an atomic strike destroys it, along with most of the Second Army."},
 {id:"caduceus",name:"Plains of Caduceus",lat:HL.caduceus[0],lon:HL.caduceus[1],site:"helios",focus:"caduceus",desc:{1:"Grasslands between the north coast and the Ladon.",5:"Grasslands between the north coast and the Ladon, where the Society’s landing waves are caught in Orion’s storms."}},
 {id:"angelia",name:"Angelia",lat:HL.angelia[0],lon:HL.angelia[1],site:"helios",focus:"angelia",desc:{1:"A small city north of Eleusis.",5:"A small city north of Eleusis. The Fear Knight booby-traps it and sets its reactor to blow."}},
 {id:"atlasbase",name:"The Fear Knight’s Lair",lat:HL.erebos[0]+3,lon:HL.erebos[1]-3,site:"atlasbase",from:5,desc:"Atlas au Raa’s Gorgon base, cut into caves in the Hesperides above Erebos. Its location is never given in the books; placed here as a reconstruction."},
 {id:"erebos",name:"Erebos",lat:HL.erebos[0],lon:HL.erebos[1],site:"helios",focus:"erebos",desc:{1:"A town in the foothills of the Hesperides.",5:"A town in the foothills of the Hesperides. Lysander is captured here by the Gorgons after the Ladon."}},
 {id:"eleusis",name:"Eleusis",lat:HL.eleusis[0],lon:HL.eleusis[1],site:"helios",focus:"eleusis",desc:"A mining city on the eastern edge of the Ladon."},
 {id:"children",name:"The Children",lat:HL.kydon[0]+3,lon:HL.kydon[1]-14,site:"helios",focus:"kydon",desc:{1:"The cities of the Petasos Peninsula on the northeast coast, among them Kydon, Pan, Kaikos and Priapos.",5:"The cities of the Petasos Peninsula on the northeast coast, among them Kydon, Pan, Kaikos and Priapos. Republic bases stand near Kydon and Pan."}},
 {id:"marcher",name:"Marcher (trash moon)",lat:8,lon:-60,site:"marcher",from:6,desc:"A trash moon where Darrow and the survivors of Mercury hide with the crippled Archimedes in Light Bringer. Its location is not given in the books; placed near Mercury here."},
 {id:"whitefleet",name:"White Fleet Graveyard (orbit)",lat:-2,lon:-30,site:"whitefleet",from:5,desc:"Outside Mercury’s orbit, the drifting wrecks of the Republic’s White Fleet. In the prologue of Dark Age, Darrow’s team rescues Orion from the Society ships combing them."},
 {id:"caliban",name:"Caliban Sea",lat:-8,lon:-38,desc:{1:"The sea west of Helios.",5:"The sea west of Helios. Wrecks of the White Fleet fall into it after Atalantia’s ambush over Tyche."}},
 {id:"polar",name:"Storm God vaults",from:5,lat:72,lon:-12,desc:"House Lune secretly buried seven Storm Gods, kilometer-wide weather machines, beneath Mercury’s polar ice as a check on House Votum. Darrow raises them in Dark Age."}
];
