    {const L=60000,rv=new THREE.PlaneGeometry(L,1,3000,1);rv.rotateX(-Math.PI/2);const rp=rv.attributes.position;
      for(let i=0;i<rp.count;i++){const x=rp.getX(i);const side=rp.getZ(i)>0?1:-1;rp.setZ(i,riverZ(x)+side*118);rp.setY(i,-6);}rv.computeVertexNormals();
      root.add(makeWater({geometry:rv,flat:18,depthK:40,shallow:0x3f9aa0,deep:0x226a7a,offset:true,scale:.5,far:16000}));}
    const B=new GeoBuilder(),Bm=new GeoBuilder(),Bg=new GeoBuilder(),Bl=new GeoBuilder(),Bk=new GeoBuilder();
    const WHITE=[0xf2ece1,0xebe4d6,0xe2d9c8,0xf7f2ea,0xe8dfcf],ROOF_R=[0xb4402c,0xa63626,0xc24c30],GLASS=[0xc6d6e2,0xb4c8d8,0xd4e0e8,0xbccede];
