    const mists=[];HOUSES.forEach((H,i)=>{if(H.under)return;const y=ground(H.x,H.z);for(let k=0;k<(H.id==="mars"?12:8);k++){const s=new THREE.Sprite(new THREE.SpriteMaterial({map:GLOW_WHITE,color:col(0xd8dce0),transparent:true,opacity:.42,depthWrite:false,fog:true}));
      const a=R()*TAU,r=H.s*(1.2+R()*1.2),sc=H.s*(2.4+R()*1.6);s.scale.set(sc,sc*.32,1);s.position.set(H.x+Math.cos(a)*r,y-H.s*(.55+R()*.5),H.z+Math.sin(a)*r);root.add(s);mists.push(s);}});
    SITES.institute._mists=mists;
    /* Phobos and Deimos towers */
    [[-170,-3620],[-60,-3220]].forEach(p=>{const y=ground(p[0],p[1]);B.add(G.cyl(42,52,30,16),TM(p[0],y-20,p[1]),DSTONE);ARCH.tower(B,p[0],y+8,p[1],32,300,0x67625a,"cone",1);banner(p[0],y+8+300+70,p[1],0xb03526,90);});
    /* ---- Olympus: a jagged inverted crag, crowned by a tight stack of square marble towers ---- */
    const oly=new THREE.Group();oly.position.set(OLY.x,OLY.y,OLY.z);root.add(oly);
    let rock=new THREE.ConeGeometry(660,1400,12,8,false);rock.rotateX(Math.PI);rock.translate(0,-700,0);
    {const p=rock.attributes.position;for(let i=0;i<p.count;i++){const x=p.getX(i),y=p.getY(i),z=p.getZ(i);if(y>-5)continue;
        const a=Math.atan2(z,x);const k=1+(N.f(Math.cos(a)*2+3,y*.0035,Math.sin(a)*2,3)-.5)*.95;const strata=1+.07*Math.sign(Math.sin(y*.045))*(N.vn(a*3,y*.01,1)>.4?1:0);
        p.setXYZ(i,x*k*strata,y+(N.f(x*.01,2,z*.01,2)-.5)*160*(-y/1400),z*k*strata);}}
    rock=rock.toNonIndexed();rock.computeVertexNormals();
    const OB=new GeoBuilder();OB.add(rock,null,0x7e7062,0,true);
    {let top=new THREE.CylinderGeometry(670,640,60,12,1);top.translate(0,-30,0);const p=top.attributes.position;for(let i=0;i<p.count;i++){const x=p.getX(i),z=p.getZ(i);const k=1+(N.f(x*.004,5,z*.004,2)-.5)*.25;p.setX(i,x*k);p.setZ(i,z*k);}
      top=top.toNonIndexed();top.computeVertexNormals();OB.add(top,null,0x8a7c6c,0,true);}
    OB.add(G.cyl(600,600,3,24),TM(0,0,0),0x6e7a4c,0,true);
