    /* towers about it */
    [[-150,-120,80,300,"pyr"],[150,-130,74,260,0],[-170,90,70,230,0],[160,110,86,280,"pyr"],[-40,170,96,170,0],[60,-200,62,220,"pyr"],[-220,-10,60,180,0],[230,0,64,200,"pyr"],[90,190,58,150,"pyr"],[-110,-220,56,170,0]].forEach(([x,z,w,h,cap])=>slab(x,76,z,w,h,w*(.85+R()*.3),PALE[(R()*4)|0],0,cap));
    /* lower halls and a gate stair toward the south rim */
