    for(let k=0;k<7;k++){let g=new THREE.TetrahedronGeometry(50+R()*80,0);g.computeVertexNormals();const a=R()*TAU,r=220+R()*380;OB.add(g,TM(Math.cos(a)*r,-380-R()*600,Math.sin(a)*r,R(),1,1.8,1),0x6e6256,0,true);}
    const om=OB.mesh(M.clean);om.castShadow=false;oly.add(om);
    const oGlow=glowSprite(GLOW_BLUE,1300,.12);oGlow.position.y=-1000;oly.add(oGlow);
    for(let k=0;k<4;k++){const s=glowSprite(GLOW_WHITE,70,.5);s.position.set([-150,160,150,60][k],[400,380,350,310][k],[-120,110,-130,-200][k]);oly.add(s);}
    /* sea stacks off the cliffs, with foam at their feet */
