    for(let i=0;i<34;i++){const x=(R()-.5)*11000;if(cove(x)>.4)continue;const z=shoreZ(x)+40+R()*320;if(ground(x,z)>WATER_Y-5)continue;const hgt=50+R()*150,r=18+R()*34;
      const g=new THREE.CylinderGeometry(r*.6,r,hgt+40,9,5);g.translate(0,(hgt+40)/2-40,0);const pp=g.attributes.position;for(let k=0;k<pp.count;k++){const px=pp.getX(k),py=pp.getY(k),pz=pp.getZ(k);const f=1+(N.f(px*.05+i,py*.03,pz*.05,2)-.5)*.6;pp.setXYZ(k,px*f,py,pz*f);}g.computeVertexNormals();
      Bd.add(g,TM(x,WATER_Y,z,R()),[0x9a8c78,0x8a7e6c,0xa89a84][(R()*3)|0]);Bd.add(G.cyl(r*.62,r*.66,5,9),TM(x,WATER_Y+hgt-2,z),0x6a8a46,0,true);SR.push([x,z,r]);}
    /* surf: a band of white along the foot of the coast and around the stacks */
    {const pos=[],uv=[],idx=[];let n=0;for(let x=-6000;x<=6000;x+=24){let z=shoreZ(x)-200;while(z<shoreZ(x)+500&&ground(x,z)>WATER_Y)z+=6;
        [[0,-6],[1,26]].forEach(([u,o])=>{pos.push(x,WATER_Y+.6,z+o);uv.push(u,x*.01);});if(n){const k=n*2;idx.push(k-2,k-1,k,k-1,k+1,k);}n++;}
      const g=new THREE.BufferGeometry();g.setAttribute("position",new THREE.Float32BufferAttribute(pos,3));g.setAttribute("uv",new THREE.Float32BufferAttribute(uv,2));g.setIndex(idx);
      const FT=glowTexture([[0,"rgba(255,255,255,1)"],[.5,"rgba(255,255,255,.5)"],[1,"rgba(255,255,255,0)"]]);
      var surf=new THREE.Mesh(g,new THREE.MeshBasicMaterial({color:col(0xf4fbff),transparent:true,opacity:.7,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-2,polygonOffsetUnits:-4}));
      surf.material.onBeforeCompile=sh=>{sh.fragmentShader=sh.fragmentShader.replace("#include <dithering_fragment>","#include <dithering_fragment>\n gl_FragColor.a*=smoothstep(1.,.15,vUvS.x)*(.6+.4*sin(vUvS.y*40.));");
        sh.vertexShader=sh.vertexShader.replace("#include <common>","#include <common>\nvarying vec2 vUvS;").replace("#include <begin_vertex>","#include <begin_vertex>\nvUvS=uv;");sh.fragmentShader=sh.fragmentShader.replace("#include <common>","#include <common>\nvarying vec2 vUvS;");};
      root.add(surf);
      SR.forEach(([x,z,r])=>{const f=new THREE.Mesh(new THREE.RingGeometry(r*.9,r*1.8,24).rotateX(-Math.PI/2),new THREE.MeshBasicMaterial({color:col(0xf4fbff),transparent:true,opacity:.45,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-2,polygonOffsetUnits:-4}));f.position.set(x,WATER_Y+.7,z);root.add(f);});}
    root.add(B.mesh(M.clean));root.add(Bd.mesh(M.clean));
    /* ---- forests ---- */
    const god=scatter(3200,11000,R,(x,z)=>{if(!inGreat(x,z)||riverDist(x,z)<60)return null;const h=ground(x,z);if(h<WATER_Y+6)return null;if(HOUSES.some(H=>Math.hypot(x-H.x,z-H.z)<H.s*1.1))return null;return {x,y:h,z,s:20+R()*22,c:[0x2f5a2a,0x3a6630,0x2a4f26,0x44702f][(R()*4)|0]};});
    root.add(makeForest(god,"broad",11));
    const pines=scatter(9000,11000,R,(x,z)=>{const h=ground(x,z);const north=inNorth(x,z);const mount=h>140&&h<1050&&N.f(x*.003,4,z*.003,3)>.36;const vale=x<-500&&x>-2600&&h<300&&N.f(x*.0025,18,z*.0025,3)>.55;if(vale&&!north&&!mount){if(riverDist(x,z)<50||h<WATER_Y+6||HOUSES.some(H=>Math.hypot(x-H.x,z-H.z)<H.s*1.2))return null;return {x,y:h,z,s:10+R()*7,c:[0x2c4a32,0x355a3a,0x2a4430,0x3a5e3c][(R()*4)|0]};}if(!(north||mount)||riverDist(x,z)<50||h<WATER_Y+6)return null;return {x,y:h,z,s:11+R()*8,c:[0x2c4a32,0x355a3a,0x2a4430][(R()*3)|0]};});
    root.add(makeForest(pines,"pine",13));
    const copse=scatter(1400,11000,R,(x,z)=>{const h=ground(x,z);if(h>360||h<WATER_Y+8||inGreat(x,z)||inNorth(x,z)||riverDist(x,z)<40)return null;const near=riverDist(x,z)<240;if(!near&&N.f(x*.004,7,z*.004,3)<.6)return null;if(HOUSES.some(H=>Math.hypot(x-H.x,z-H.z)<H.s*1.1))return null;return {x,y:h,z,s:8+R()*7,c:[0x4f6f34,0x5e7b3a,0x6d8640][(R()*3)|0]};});
    root.add(makeForest(copse,"broad",17));
