    const clouds=[];const CT=glowTexture([[0,"rgba(255,255,255,.95)"],[.35,"rgba(250,250,252,.6)"],[.7,"rgba(240,242,248,.18)"],[1,"rgba(0,0,0,0)"]]);
    const cloud=(x,y,z,size,op)=>{const n=5+((R()*5)|0);for(let k=0;k<n;k++){const s=new THREE.Sprite(new THREE.SpriteMaterial({map:CT,transparent:true,opacity:op*(.7+R()*.3),depthWrite:false,fog:true}));
        const sc=size*(.5+R()*.6);s.scale.set(sc,sc*.5,1);s.position.set(x+(R()-.5)*size*1.3,y+(R()-.3)*size*.18,z+(R()-.5)*size*.6);s.userData.base=s.material.opacity;root.add(s);clouds.push(s);}};
    /* a high deck drifting past Olympus, a band over the mountains, and low banks in the valleys */
    for(let i=0;i<20;i++)cloud((R()-.5)*10000,1500+R()*600,(R()-.5)*8000,900+R()*700,.55);
    for(let i=0;i<14;i++)cloud(-3600+(R()-.5)*1600,900+R()*500,-4000+R()*6500,700+R()*500,.6);
    for(let i=0;i<10;i++)cloud(OLY.x+(R()-.5)*2400,OLY.y-1400-R()*500,OLY.z+(R()-.5)*2000,600+R()*400,.45);
    SITES.institute._snow=k=>{terr.userData.setSnow(k);MAT.tree.emissive.copy(col(0xb8c0c8)).multiplyScalar(k*.45);seaU.wShallow.value.copy(SEA_S).lerp(col(0xdfe8ee),k*.7);seaU.wDeep.value.copy(SEA_D).lerp(col(0xb8c8d4),k*.6);};
    /* ---- war bands: the Institute's main fights in book order ---- */
