      const HP=id=>{if(id==="olympus")return {x:OLY.x,z:OLY.z+60,s:420,c:0xffffff};return HOUSES.find(h=>h.id===id);};
      const COL={mars:0xb03526,minerva:0x3b5f9a,diana:0x3f7a4a,ceres:0xd2a645,apollo:0xe0b84a,jupiter:0x6a4aa0};
      const STEPS=[
        {t:"Minerva breaks Titus",s:"Darrow lures House Minerva onto Titus’s faction of Mars; Mustang’s House routs it, then falls back.",m:[{h:"minerva",a:"minerva",b:"mars",n:80},{h:"mars",a:"mars",b:"mars",n:30,def:1}]},
        {t:"Diana and Minerva enslaved",s:"Darrow outwits House Diana and most of House Minerva and takes them as slaves. Mustang escapes with her standard.",m:[{h:"mars",a:"mars",b:"diana",n:60},{h:"mars",a:"mars",b:"minerva",n:60},{h:"diana",a:"diana",b:"diana",n:30,def:1},{h:"minerva",a:"minerva",b:"minerva",n:30,def:1}]},
        {t:"Ceres and Apollo fall",s:"Darrow’s army, swollen with slaves, conquers House Ceres and House Apollo.",m:[{h:"mars",a:"minerva",b:"ceres",n:70},{h:"mars",a:"diana",b:"apollo",n:80},{h:"ceres",a:"ceres",b:"ceres",n:30,def:1},{h:"apollo",a:"apollo",b:"apollo",n:30,def:1}]},
        {t:"The storm on Olympus",s:"Darrow’s army rises on the Proctors’ own flying boots, frees Mustang and captures the Proctors.",m:[{h:"mars",a:"ceres",b:"olympus",n:70,fly:1},{h:"mars",a:"apollo",b:"olympus",n:70,fly:1},{h:"minerva",a:"minerva",b:"olympus",n:40,fly:1}]},
        {t:"Darrow retakes House Mars",s:"Back on the ground, Darrow unseats Cassius and takes command of House Mars again.",m:[{h:"mars",a:"olympus",b:"mars",n:80,from:1}]}];
      const STEP=18;const soldierG=new THREE.CylinderGeometry(5,6.5,28,6).translate(0,14,0);const flagG=new THREE.PlaneGeometry(70,44).translate(35,0,0);const poleG=new THREE.CylinderGeometry(2,2,120,5).translate(0,60,0);
