    const B=new GeoBuilder(),Bm=new GeoBuilder(),Bg=new GeoBuilder(),Bl=new GeoBuilder();
    const WHITE=[0xf4f1ea,0xebe6dc,0xe2ddd2,0xf8f6f0],PALE=[0xd6dde4,0xc8d2dc,0xe0e4e6],GREY=[0x6a6664,0x76716c,0x5e5a58,0x847d74,0x8e877e];
    /* night light layers: warm windows, white lamps, gold street lines */
