    /* Esqueline villas */
    for(let i=0;i<46;i++){const a=R()*TAU,r=R()*560;const x=CIT.x+800+Math.cos(a)*r,z=CIT.z+800+Math.sin(a)*r,y=ground(x,z);if(platD(x,z)>1400)continue;const ry=R();B.add(G.box(40,18,30),TM(x,y,z,ry),0xf2eee6);B.add(G.gable(42,12,32),TM(x,y+18,z,ry),0xb08a4a);warm.push(x,y+10,z);}
    /* Dragon Maw: a dark shaft with a ring of light */
    {const x=CIT.x+260,z=CIT.z-260,y=ground(x,z);B.add(G.torus(70,10,40),TM(x,y+4,z,0,1,1,1,Math.PI/2),0x2a2a2e);B.add(G.cyl(64,64,2,32),TM(x,y+1,z),0x050506,0,true);
      const ring=new THREE.Mesh(new THREE.TorusGeometry(70,3,8,48),new THREE.MeshBasicMaterial({color:col(0xff9a50)}));ring.rotation.x=Math.PI/2;ring.position.set(x,y+9,z);root.add(ring);}
    /* ================= viaducts: arched causeways with lamps ================= */
