    const warm=[],lanterns=[];
    const col_=(x,y,z,h,r)=>{B.add(G.cyl(r,r*1.12,h,12),TM(x,y,z),MARB);B.add(G.box(r*2.6,r*.8,r*2.6),TM(x,y+h,z),MARB);B.add(G.box(r*2.6,r*.6,r*2.6),TM(x,y,z),MARB);};
    const row=(x0,z0,x1,z1,y,h,n,r)=>{for(let i=0;i<n;i++){const t=n>1?i/(n-1):.5;col_(x0+(x1-x0)*t,y,z0+(z1-z0)*t,h,r);}};
    /* a hall with a pitched tile roof and a pediment */
    const hall=(x,y,z,w,h,d,ry,porch)=>{B.add(G.box(w,h,d),TM(x,y,z,ry),ST[(R()*4)|0]);B.add(G.box(w+8,5,d+8),TM(x,y+h,z,ry),MARB);
      B.add(G.gable(w+10,h*.32,d+10),TM(x,y+h+5,z,ry),ROOF);
      const ca=Math.cos(ry),sa=Math.sin(ry);
      for(let i=0;i<Math.floor(w/22);i++){const u=-w/2+11+i*22;[d/2+.5,-d/2-.5].forEach(v=>{const px=x+u*ca+v*sa,pz=z-u*sa+v*ca;Bl.add(G.box(8,h*.5,1),TM(px,y+h*.22,pz,ry),0xffd49a,0,true);warm.push(px+sa*4*(v>0?1:-1),y+h*.45,pz+ca*4*(v>0?1:-1));});}
      if(porch){const pd=porch;const n=Math.max(4,Math.floor(w/26));for(let i=0;i<n;i++){const u=-w/2+w*(i+.5)/n;const px=x+u*ca+(d/2+pd*.6)*sa,pz=z-u*sa+(d/2+pd*.6)*ca;col_(px,y,pz,h,4.2);}
        B.add(G.box(w,6,pd),TM(x+(d/2+pd/2)*sa,y+h,z+(d/2+pd/2)*ca,ry),MARB);B.add(G.gable(w+4,h*.3,pd+4),TM(x+(d/2+pd/2)*sa,y+h+6,z+(d/2+pd/2)*ca,ry),ROOF2);}};
    const gy=(x,z)=>ground(x,z);
