    B.add(G.box(1160,10,90),TM(VX,-4,TER[0][0]+20),0xd6ccb6);
    row(VX-560,TER[0][0]-20,VX+560,TER[0][0]-20,6,34,30,3.4);B.add(G.box(1140,5,12),TM(VX,40,TER[0][0]-20),MARB);
    for(let i=0;i<30;i++)lanterns.push(VX-560+i*38.6,30,TER[0][0]-26);
    /* stairs between the terraces */
    TER.forEach((t,i)=>{if(!i)return;const h0=TER[i-1][2],h1=t[2];for(let k=0;k<8;k++){const y=h0+(h1-h0)*k/8;B.add(G.box(120,(h1-h0)/8+1,6),TM(VX,y,t[0]-24+k*3),MARB);}
      ARCH.wall(B,VX-600,t[0]-2,VX-70,t[0]-2,h0,h1-h0+6,6,0xddd3bf);ARCH.wall(B,VX+70,t[0]-2,VX+600,t[0]-2,h0,h1-h0+6,6,0xddd3bf);
      for(let k=0;k<14;k++){const x=VX-560+k*86;if(Math.abs(x-VX)<90)continue;lanterns.push(x,h1+8,t[0]-2);}});
    /* ---- the main house: a long hall with a portico facing the lake, wings around a peristyle ---- */
    const y2=TER[1][2],y3=TER[2][2],y4=TER[3][2];
