    const Lw=new THREE.Points(new THREE.BufferGeometry().setAttribute("position",new THREE.Float32BufferAttribute(warm.concat(lanterns),3)),new THREE.PointsMaterial({color:col(0xffd49a),size:4.5,sizeAttenuation:false,map:GLOW_WARM,transparent:true,opacity:0,depthWrite:false,blending:THREE.AdditiveBlending}));Lw.frustumCulled=false;root.add(Lw);
