    SITES.silene.onTod=n=>{Lw.material.opacity=.15+n*.85;glows.forEach(s=>s.material.opacity=n*.8);farPts.material.opacity=.2+n*.8;refl.material.opacity=n*.22;orb.material.opacity=.3+n*.5;};
