  for(let k=0;k<22;k++){const x=-54+k*5.2;[-1,1].forEach(sd=>K.add(new THREE.CylinderGeometry(.8,.8,1,6).rotateX(Math.PI/2),at(V(x,22,sd*42.5)),0x2a2420,0,true));}
