  for(let k=0;k<9;k++)K.add(new THREE.BoxGeometry(1.2,22,46),at(V(-70-k*2.4,24,0)),0x2a201c,0,true);
  [-16,0,16].forEach(z=>{K.add(new THREE.CylinderGeometry(2.6,3.4,26,14),at(V(-40,60,z)),0x3a2e28,0,true);K.add(new THREE.CylinderGeometry(3.2,3.2,2,14),at(V(-40,73,z)),0x1a1410,0,true);Lm.add(new THREE.CylinderGeometry(2.2,2.2,.6,14),at(V(-40,74.2,z)),0xff6a2a,2,true);});
  /* hydraulic rams and cable runs along the flanks */
  [-1,1].forEach(sd=>{for(let k=0;k<3;k++){K.add(new THREE.CylinderGeometry(1.6,1.6,34,10).rotateZ(Math.PI/2),at(V(-20+k*24,-2,sd*34)),0x9a9088,0,true);K.add(new THREE.CylinderGeometry(2.6,2.6,14,10).rotateZ(Math.PI/2),at(V(-30+k*24,-2,sd*34)),0x3a302a,0,true);}});
  /* the cab and its canopy */
  D.add(bevelBox(34,20,36,6),at(V(56,58,0)),RED[1],0,true);
  D.add(bevelBox(26,8,30,3),at(V(52,70,0)),RED[4],0,true);
  Lm.add(bevelBox(16,8,28,2.5),at(V(70,60,0),QZ(-.5)),0xffb070,2,true);
