  [[-1],[1]].forEach(([sd])=>{for(let k=0;k<3;k++){const sh=V(-36+k*36,10,sd*40);const far=V(-120+k*95,-60+(k===1?30:0),sd*(230+R()*40));const up=V(-60+k*45,120+k*16,sd*(140+R()*20));
    limb(bez(sh,up,far,6),12,7.5,k+(sd>0?1:0));}});
  /* two upper arms reaching up to the roof of the bore */
  [[-1],[1]].forEach(([sd])=>{const sh=V(20,58,sd*30);limb(bez(sh,V(60,190,sd*80),V(150,250,sd*170),6),10,6,2);});
