  const sa=V(60,6,0),ea=V(150,70,0),wa=V(230,40,0);seg(sa,ea,20,RED[1]);seg(ea,wa,16,RED[0]);
  g.add(D.mesh(mats().metal));g.add(K.mesh(mats().cleanMetal));
