  H.add(new THREE.CylinderGeometry(34,34,6,24).rotateZ(-Math.PI/2),at(V(-12,0,0)),0x3a302a,0,true);
  for(let k=0;k<12;k++){const a=k/12*TAU;H.add(new THREE.ConeGeometry(5,40,8).rotateZ(-Math.PI/2).translate(30,0,0),at(V(0,Math.cos(a)*22,Math.sin(a)*22),new THREE.Quaternion().setFromEuler(new THREE.Euler(a,0,-.25))),0xd8d0c4,0,true);}
  H.add(new THREE.ConeGeometry(14,56,16).rotateZ(-Math.PI/2).translate(40,0,0),null,0xe8e0d4,0,true);
