  facts:[["Clan","Lambda"],["Homes","Cut into the rock and built out from it"],["Nearby","The Webbery, the duct to the Bubble Garden"]],
  note:"Street-level layout is an artistic reconstruction.",
  todLabel:{day:"Shift",dusk:"Laureltide",night:"Lights down"},
  ground,targetLift:0,bounds:700,minR:8,maxR:1500,shadow:520,win:[1.2,1.0],winK:1.6,cam:{target:[0,30,0],r:420,theta:.75,phi:1.3},defaultTod:"day",
