          if(R()<.4)B.add(G.box(w*.7,h*.4,out*.7+4),TM(cx+(R()-.5)*4,y0+h,wz+out*.35-2),ROCK[(R()*ROCK.length)|0]);
          /* door, curtain and lintel */
          const dz=wz+out+2.1;Bm.add(G.box(7,13,.8),TM(cx-w*.2,y0,dz),0x140c08,0,true);Bm.add(G.box(6.4,11,.4),TM(cx-w*.2,y0,dz+.5),isHome?0xa8281a:CLOTH[(R()*CLOTH.length)|0],0,true);
          Bm.add(G.box(10,1.4,2),TM(cx-w*.2,y0+13.5,dz),0x4a3426);
