      for(let i=0;i<p.count;i++){const x=p.getX(i),y=p.getY(i),z=p.getZ(i);const k=1+(N.f(x*.003,y*.003,z*.003,4)-.5)*.9;if(y<-5)p.setXYZ(i,x*k,y+(N.f(x*.01,z*.01,4,2)-.5)*80,z*k);
        const n=N.f(x*.006,y*.004,z*.006,3);ca.copy(col(0x34363c)).lerp(col(0x6a6e78),n);if(n>.66)ca.lerp(col(0xe8f0f8),.7);c.push(ca.r,ca.g,ca.b);}
      rock.setAttribute("color",new THREE.Float32BufferAttribute(c,3));rock.computeVertexNormals();const rm=new THREE.Mesh(rock,sm);rm.castShadow=true;ast.add(rm);
      const A=new GeoBuilder();A.add(G.cyl(920,900,70,40),TM(0,-70,0),0x4a4c52,0,true);A.add(G.cyl(880,880,4,40),TM(0,0,0),0xe6eef6,0,true);
      for(let k=0;k<16;k++){const a=k/16*TAU;ARCH.tower(A,Math.cos(a)*780,0,Math.sin(a)*780,34,190,0x2e3036,null,1);}
      A.add(G.box(420,220,280),TM(0,0,0),0x262830,1);A.add(G.box(300,120,200),TM(0,220,0),0x2e3038,1);ARCH.spire(A,0,340,0,50,560,0x3a3c44,0x9fd0ff);
