      snow.position.set(camX.position.x-camX.position.x%3000,0,camX.position.z-camX.position.z%3000);const a=g.attributes.position;for(let i=0;i<n;i++){let x=a.getX(i)+dt*220,y=a.getY(i)-dt*60;if(x>1500)x=-1500;if(y<0)y=1500;a.setX(i,x);a.setY(i,y);}a.needsUpdate=true;
