 {id:"graveyard",name:"Graveyard of Tyrants",pos:[P.grave[0],300,P.grave[2]],desc:"Seven monoliths raised to honor Sovereigns. The Republic dumped them at the edge of the Ladon and left them to sink into the sand.",cam:{target:P.grave,r:1800,theta:.9,phi:1.0}},
 {id:"votum",name:"Mound of Votum",pos:[P.votum[0],800,P.votum[2]],desc:"House Votum’s vast basilica on the Bay of Sirens, west of the city, with a statue of Helios about half a kilometer tall and the Votum war room. Darrow falls back here and Cassius carries him out aboard the Archimedes.",cam:{target:[P.votum[0],200,P.votum[2]],r:2600,theta:-.3,phi:1.05}},
 {id:"marina",name:"The Corniche",pos:[P.marina[0],80,P.marina[2]],desc:"The city’s waterfront on the Bay of Sirens: promenades, marinas and the mouth of the grand canal.",cam:{target:[P.marina[0],0,P.marina[2]],r:2200,theta:-.4,phi:1.05},minor:true},
 {id:"bay",name:"Bay of Sirens",pos:[P.bay[0],60,P.bay[2]],desc:"The bay west of the city. Glirastes’ floating home, the Lady Beatrice, hangs above the city; the Lightbringer is unveiled in the skies here in Light Bringer.",cam:{target:[P.bay[0],0,P.bay[2]],r:5200,theta:-.5,phi:1.1}}
