      T.taper.push([x,y,z,150,h*.9,150,0,i===1?0xcadae4:0xf6f1e8]);for(let k=1;k<6;k++)T.gold.push([x,y+h*.9*k/6,z,150*(1-.74*k/6)*1.06,10,150*(1-.74*k/6)*1.06,0,0xd9b060]);T.cone.push([x,y+h*.9,z,44,h*.14,44,0,0xd9b060]);
