      B.add(G.box(1080,3,520),TM(x,y-.5,z),0xc8a878,0,true);B.add(G.box(820,10,22),TM(x,y,z),0xf3eee4);for(let k=0;k<7;k++){Bg.add(G.cone(10,70,8),TM(x-360+k*120,y+10,z),0xffffff);}
