    {const x=CAVE.x+HALF_W+260,z=CAVE.z+CAVE.r*.95+60;const g=new THREE.PlaneGeometry(60,700,1,20);const m=new THREE.Mesh(g,fallMat);m.position.set(x,terrH(x,z-80)-320,z);root.add(m);const mist=glowSprite(GLOW_WHITE,320,.45);mist.position.set(x,60,z+40);root.add(mist);
      root.add(makeWater({y:22,ground:terrH,extent:3200,cx:700,cz:CAVE.z+CAVE.r*.95+1900,res:256,span:60}));}
    root.add(B.mesh(M.bld));root.add(Bm.mesh(M.cleanMetal));
    const trees=scatter(9000,14000,R,(x,z)=>{const y=terrH(x,z);if(y<60||y>1800)return null;const sl=Math.abs(terrH(x+20,z)-y)+Math.abs(terrH(x,z+20)-y);if(sl>24)return null;return {x,y,z,s:10+R()*8,c:[0x2f5a2a,0x3a6630,0x2a4f26][(R()*3)|0]};});
    root.add(makeForest(trees,"pine",17));
