    function claim(p,r){const k=Math.floor(p.x/CELL)+","+Math.floor(p.y/CELL)+","+Math.floor(p.z/CELL);if(!hash.has(k))hash.set(k,[]);hash.get(k).push({p:p.clone(),r});}
