    /* ---------- the Necromancer and the shuttle ---------- */
    const necro=new THREE.Group();const nm=new THREE.Mesh(necroGeo(),nMat);nm.scale.setScalar(5.4);nm.castShadow=true;nm.receiveShadow=true;necro.add(nm);
