    necro.position.copy(HIDE);necro.rotation.y=-.4;root.add(necro);
    const shuttle=new THREE.Group();const shm=new THREE.Mesh(shuttleGeo(),shipMats());shm.scale.setScalar(2.6);shm.castShadow=true;shuttle.add(shm);
    const shEng=glowSprite(GLOW_BLUE,40,.95);shEng.position.set(-15*2.6,0,0);shuttle.add(shEng);shuttle.visible=false;root.add(shuttle);

