    place("moonbreaker",2800,HIDE_WRECK.clone(),new THREE.Quaternion().setFromEuler(new THREE.Euler(.15,.9,.25)),0,{hide:true});claim(HIDE_WRECK,1100);
    /* the cores Darrow and Alexander prime: a ring around the picket and a wall flanking the escape lane */
