      for(let i=0;i<14;i++)for(const s of [-1,1]){B.add(G.cyl(5,6,90,14),TM(x-130+i*20,y+22,z+s*62),0xf6f1e6);}for(let i=0;i<6;i++)for(const s of [-1,1])B.add(G.cyl(5,6,90,14),TM(x+s*130,y+22,z-50+i*20),0xf6f1e6);
      B.add(G.box(270,10,136),TM(x,y+112,z),0xece6d8);B.add(G.gable(150,36,284),TM(x,y+122,z,Math.PI/2),0xf0eadc);B.add(G.box(200,80,90),TM(x,y+22,z),0xe2dccc);
