    {for(let k=0;k<10;k++){const x=ACRO.x+120+(k%2)*60,z=ACRO.z-160+k*26;Bm.add(G.box(120,4,8),TM(x,top+6,z),0x4a3424);for(let j=0;j<6;j++)Bm.add(G.box(4,6,4),TM(x-50+j*20,top,z),0x3a2a1c);}
      for(let i=0;i<14;i++){const a=R()*TAU,r=60+R()*260;const x=ACRO.x+Math.cos(a)*r,z=ACRO.z+Math.sin(a)*r;fires.push([x,top+6,z,1+R()]);}
      for(let i=0;i<26;i++){const a=R()*TAU,r=120+R()*240;const x=ACRO.x+Math.cos(a)*r,z=ACRO.z+Math.sin(a)*r;Bm.add(G.box(1.4,40,1.4),TM(x,top,z),0x2a1e16);Bm.add(G.box(14,22,.5),TM(x+7,top+16,z),[0x5a2a1a,0x3a2a20,0x6a3a24][(R()*3)|0]);}}
    /* the duel dome */
    const dome=shieldDome(90,0xff9a50);dome.position.set(ACRO.x+220,top,ACRO.z-120);root.add(dome);
