    ISLES.slice(1).forEach(([ix,iz,r,ih],k)=>{if(ix===HADES.x)return;for(let i=0;i<120;i++){const a=R()*TAU,rr=Math.sqrt(R())*r*.75;const x=ix+Math.cos(a)*rr,z=iz+Math.sin(a)*rr;const y=ground(x,z);if(y<6)continue;
        const w=14+R()*16;T.box.push([x,y-2,z,w,8+R()*20,w*(.8+R()*.4),R()*3,MARB[(R()*3)|0]]);if(R()<.6)T.dome.push([x,y+16,z,w*.6,w*.3,w*.6,0,[0x3a6a9a,0x2a5a8a,0xd9b060][(R()*3)|0]]);if(R()<.4)warm.push(x,y+8,z);}});
    /* the headland of Hades: black cliffs and a ruined watchtower */
    {const y=ground(HADES.x,HADES.z);B.add(G.cyl(24,30,90,10),TM(HADES.x,y-6,HADES.z),0x3a3634);B.add(G.box(60,24,40),TM(HADES.x+40,y-4,HADES.z+30,.4),0x3a3634);}
