      const finG=(()=>{const sh=new THREE.Shape();sh.moveTo(0,0);sh.quadraticCurveTo(30,-10,90,-46);sh.quadraticCurveTo(40,-6,6,18);sh.lineTo(0,0);return new THREE.ExtrudeGeometry(sh,{depth:3,bevelEnabled:true,bevelSize:1.5,bevelThickness:1.5,bevelSegments:2,curveSegments:10});})();
