      const eyes=[1,-1].map(s=>{const e=glowSprite(GLOW_BLUE,22,.9);grp.add(e);return e;});
      const lumin=GlowPoints(grp,80);const lspots=[];for(let k=0;k<80;k++)lspots.push({t:.1+R()*.8,a:R()*TAU});
      const spine=[],tan=[],nrm=[],bin=[];for(let i=0;i<=SEG;i++){spine.push(new THREE.Vector3());tan.push(new THREE.Vector3());nrm.push(new THREE.Vector3());bin.push(new THREE.Vector3());}
