    const fa=new THREE.Group();{const F=new GeoBuilder();F.add(G.cyl(3,4,18,10),TM(0,0,0),0x1a1614);F.add(G.sphere(3,10),TM(0,20,0),0x2a2420);F.add(G.box(14,3,3),TM(0,16,0),0x1a1614);fa.add(F.mesh(M.cleanMetal));const g=glowSprite(GLOW_WARM,26,.7);g.position.y=12;fa.add(g);}
    fa.position.set(BAY.x-60,ALT_Y+14,BAY.z);fa.visible=false;root.add(fa);
    const flashL=new THREE.PointLight(col(0xffd0a0),0,2400,1.4);root.add(flashL);
    /* the set piece's state, driven by FX.holykill */
    const K={t:-1};
    SITES.nixian._kill=K;
    function spawnSpray(c,n,s){for(let k=0;k<n;k++){const o=sp[(Math.random()*sp.length)|0];if(o.age<o.life)continue;o.p.set(c.x+(Math.random()-.5)*s,c.y,c.z+(Math.random()-.5)*s);o.v.set((Math.random()-.5)*120,80+Math.random()*220,(Math.random()-.5)*120);o.age=0;o.life=1.5+Math.random()*1.5;}}
