function ground(x,z){let h=(N.f(x*.0007,0,z*.0007,5)-.5)*220+(N.f(x*.004,2,z*.004,3)-.5)*30;
  const d=Math.hypot(x-HEL.x,z-HEL.z);h=h*sst(HEL.r*.6,HEL.r*1.3,d)+20*(1-sst(HEL.r*.6,HEL.r*1.3,d));
  /* the trench to the south, the cliff the mine is cut into to the northwest */
  h-=sst(900,300,Math.abs(z-1800-Math.sin(x*.0012)*300))*500;
  const dm=(x-MINE.x)*.7+(z-MINE.z)*-.7;h+=sst(-200,500,-dm-Math.hypot(x-MINE.x,z-MINE.z)*.0)*0;
  const cliff=sst(-300,100,-(x+1100)-(z+500)*.6);h+=cliff*900*(.7+.3*N.f(x*.003,4,z*.003,3));
  /* rock pinnacles */
  const p=Math.pow(Math.max(0,N.f(x*.0018,7,z*.0018,3)-.62),1.4)*2400;h+=p*sst(HEL.r*1.2,HEL.r*2,d);
  const dmn=Math.hypot(x-MINE.x-200,z-MINE.z-200);if(dmn<420)h=h*sst(260,420,dmn)+(N.f(x*.01,3,z*.01,2)-.5)*10*(1-sst(260,420,dmn));
  return h;}
function color(x,z,h,sl){let c=mixc([52,62,66],[78,88,86],N.f(x*.003,1,z*.003,3));c=mixc(c,[96,104,92],sst(.6,.8,N.f(x*.012,2,z*.012,2))*.5);
  if(sl>.5)c=mixc(c,[40,46,52],(sl-.5)*1.4);if(Math.hypot(x-HEL.x,z-HEL.z)<HEL.r*.9)c=mixc([86,92,96],[104,110,112],N.f(x*.02,5,z*.02,2));
  if(h<-200)c=mixc(c,[20,26,34],sst(-200,-500,h));return c;}
