      root.add(Bm.mesh(M.cleanMetal));
      const n=7000;const geo=new THREE.CylinderGeometry(.9,1.1,4.4,5).translate(0,2.2,0);const im=new THREE.InstancedMesh(geo,new THREE.MeshStandardMaterial({color:col(0x3a4a52),roughness:.9}),n);const m4=new THREE.Matrix4();let c=0;
      for(let i=0;i<n*2&&c<n;i++){const a=R()*TAU,r=60+Math.sqrt(R())*200;const px=x+200+Math.cos(a)*r,pz=z+200+Math.sin(a)*r;m4.compose(new THREE.Vector3(px,y,pz),new THREE.Quaternion(),new THREE.Vector3(1,.9+R()*.25,1));im.setMatrixAt(c++,m4);if(R()<.06)warm.push(px,y+5,pz);}
