      vort.forEach((v,i)=>{v.a+=v.w*dt;_T.set(EYE.x+Math.cos(v.a)*v.r,v.y+Math.sin(v.a*3+i)*30,EYE.z+Math.sin(v.a)*v.r);VP.set(i,_T,v.sz,.6,.9,1,.35);});VP.setScale(pxs);VP.flush();
