    const B=new GeoBuilder(),Bg=new GeoBuilder(),Bm=new GeoBuilder(),Bw=new GeoBuilder();const warm=[],gold=[],red=[];
    const WHITE=[0xf2ece0,0xe6dccb,0xd8ccb8],GOLD=0xd9b060;
