      ARCH.colonnade(B,C.x,top+50,C.z+16,300,100,14,0xf6f1e8,0);
      for(let i=0;i<6;i++){const a=i/6*TAU+.3;const x=C.x+Math.cos(a)*200,z=C.z+Math.sin(a)*200;ARCH.spire(Bg,x,top+40,z,14,360+R()*120,0xd0d8e0,GOLD);red.push(x,top+40+480,z);}
