    for(let r=0;r<6;r++){let x=-8000+R()*16000,z=-8000+R()*16000;if(Math.hypot(x,z)<2400){x+=3000;}const pts=[];for(let k=0;k<160;k++){const e=1e-3,h0=ground(x,z);let gx=ground(x+40,z)-h0,gz=ground(x,z+40)-h0;const L=Math.hypot(gx,gz)||1;const a=Math.atan2(-gz,-gx)+(N.f(k*.1,r,0,1)-.5)*1.2;x+=Math.cos(a)*60;z+=Math.sin(a)*60;if(Math.hypot(x,z)<1700)break;pts.push(new THREE.Vector3(x,ground(x,z)+3,z));}
      if(pts.length<10)continue;const curve=new THREE.CatmullRomCurve3(pts);const n=pts.length*3;const pos=[],uv=[],idx=[];for(let i=0;i<=n;i++){const u=i/n;const p=curve.getPoint(u),tg=curve.getTangent(u);const sx=-tg.z,sz=tg.x;const L=Math.hypot(sx,sz)||1;const w=20+N.f(u*8,r,1,1)*30;
        [-1,1].forEach(s=>{pos.push(p.x+sx/L*w*s,ground(p.x+sx/L*w*s,p.z+sz/L*w*s)+4,p.z+sz/L*w*s);uv.push(u,s<0?0:1);});if(i<n){const a=i*2;idx.push(a,a+1,a+2,a+1,a+3,a+2);}}
      const g=new THREE.BufferGeometry();g.setAttribute("position",new THREE.Float32BufferAttribute(pos,3));g.setAttribute("uv",new THREE.Float32BufferAttribute(uv,2));g.setIndex(idx);root.add(new THREE.Mesh(g,lavaMat));
      for(let k=0;k<pts.length;k+=20){const s=glowSprite(GLOW_RED,300,.4);s.position.copy(pts[k]).y+=40;root.add(s);}}
    /* ---- volcanoes with their plumes: umbrella fountains of glowing ash ---- */
    const plumes=[];VOLC.forEach((v,i)=>{const y=ground(v[0],v[1]);const L=new THREE.PointLight(col(0xff6a20),2.2,3000,1.4);L.position.set(v[0],y+200,v[1]);root.add(L);const gl=glowSprite(GLOW_RED,1400,.8);gl.position.set(v[0],y+200,v[1]);root.add(gl);
      const n=900,P=GlowPoints(root,n),p=[];for(let k=0;k<n;k++)p.push({a:R()*TAU,v:.6+R()*.4,ph:R(),s:6+R()*16});plumes.push({x:v[0],y,z:v[1],P,p,H:3000+i*600,gl});});
    /* ---- the breach and the frozen dead (Light Bringer) ---- */
