      for(let i=0;i<n*2&&c<n;i++){const a=R()*TAU,r=Math.sqrt(R())*1100;const x=C.x+Math.cos(a)*r,z=C.z+Math.sin(a)*r;q.setFromEuler(new THREE.Euler(0,R()*6,0));m4.compose(new THREE.Vector3(x,ground(x,z)+.3,z),q,new THREE.Vector3(1,1,1));im.setMatrixAt(c++,m4);}
