window.__atlas={SITES,POIS,BODIES,get ERA(){return ERA;},selectBook,toSystem:()=>toSystem(),descendThen:(id,f)=>descendThen(id,f||(()=>{})),get gRot(){return gRot;},get ctl(){return ctl;},get mode(){return mode;},makeShip,col,glowSprite,GLOW_WARM,get fx(){return fxList;},setTodNow:k=>{if(curSite&&curSite.tods[k]){tod.cur=k;tod.t=1;tod.from=null;applyTod(curSite.tods[k],curSite.tods[k],1);}},enterSite,gotoEvent,EV,playFx,renderer,site3,sSun,sHemi,camX,sctl,skyMat,WIN_U,tod,get curSite(){return curSite;},THREE};

