/* ---- 62-tour.js ---- */
/* ===================== GUIDED TOURS =====================
   A chained walk through one book's places: each step flies to a place and one of its landmarks, with a line
   of story. Prev and Next move through it; you can look around freely at every stop. */
(function(){
const TOURS={book1:{title:"Red Rising · a tour of Mars",steps:[
  {site:"lykosmine",lm:"diver",t:"The Helldiver",s:"Darrow, sixteen, is the youngest Helldiver in Lykos, running the ClawDrill through the hot rock of the deep mine after helium-3."},
  {site:"lykos",lm:"laurel",t:"The Laurel",s:"Every quarter the clan that mines the most wins the Laurel. Darrow pushes Lambda to win it, but the prize is rigged to keep the clans competing."},
  {site:"lambda",lm:"home",t:"Home in Lambda",s:"Up on the terraces Darrow lives with his family, and with Eo, whom he married young as Reds do."},
  {site:"lykos",lm:"garden",t:"The Bubble Garden",s:"Eo leads him through a duct from the Webbery to a hidden grove. They are caught and whipped for it."},
  {site:"lykos",lm:"gallows",t:"Eo’s Song",s:"Eo sings the forbidden song and is hanged for it. Darrow buries her, is hanged in turn, and survives because his uncle Narol drugged him."},
  {site:"yorkton",lm:"carver",t:"Carved into a Gold",s:"The Sons of Ares take him in. Mickey the Carver remakes his body into a Gold’s, and Matteo teaches him how Golds speak and move."},
  {site:"institute",lm:"passage",t:"The Passage",s:"On the first night at the Institute, students are paired off and must kill to survive. Darrow kills Julian au Bellona."},
  {site:"institute",lm:"castle_mars",t:"House Mars",s:"Mars fractures. Darrow earns the name Reaper, and later Cassius stabs him and leaves him for dead. Mustang saves him."},
  {site:"institute",lm:"olympus",t:"Storming Olympus",s:"Darrow’s army takes the Proctors’ stronghold, frees Mustang and wins the Institute."},
  {site:"agea",lm:"citadel",t:"House Augustus",s:"Nero au Augustus offers Darrow a place as his lancer. The Red from Lykos is now inside the house that hanged his wife."}]}};

TOURS.book5={title:"Dark Age · a tour of Mercury and beyond",steps:[
  {site:"whitefleet",lm:"isship",t:"The White Fleet’s grave",s:"Among the wrecks of the Republic’s White Fleet, Darrow’s team rescues Orion from a prison ship while the Society’s picket combs the graveyard."},
  {site:"heliopolis",lm:"hippodrome",t:"Heliopolis",s:"Darrow’s army holds the golden city on Mercury’s coast against the Society’s armies."},
  {site:"ladon",lm:"wall",t:"The Eater of Armies",s:"Darrow wakes the Storm Gods. A sandstorm the size of a country rolls across the Waste of Ladon, and legions of Golds die trying to outrun it."},
  {site:"atlasbase",lm:"lair",t:"The Fear Knight",s:"Atlas au Raa runs his Gorgons from caves in the Hesperides, and Lysander is taken near Erebos."},
  {site:"tyche",lm:"libraries",t:"Tyche",s:"The City of Libraries, its great sculpted heads above the sea, drowns when the flood comes."},
  {site:"pandora",lm:"hangar",t:"The Pandora",s:"In Mars space the Ascomanni board Victra’s flagship. She releases a nerve agent and escapes; her craft crashes in Cimmeria with Lyria aboard."}]};
TOURS.book6={title:"Light Bringer · a tour of the war",steps:[
  {site:"marcher",lm:"base",t:"Marcher",s:"After Mercury falls, Darrow and some two hundred survivors hide for months on a trash moon with the crippled Archimedes."},
  {site:"rome",lm:"summit",t:"The Summit of the Two Hundred",s:"In Rome’s sun-baked Colosseum, Lysander defies Atalantia and gathers support for attacking Mars."},
  {site:"asteroid",lm:"garden",t:"The Tabula Rasa",s:"In the Belt, Quicksilver’s secret: a generation ship, and a garden of children who bear no Color at all."},
  {site:"phobos",lm:"nucleus",t:"The Fall of Phobos",s:"Virginia commands the defense from the Nucleus until Mercury’s railguns and Lysander’s crewless destroyers break the shield."},
  {site:"sungrave",lm:"breach",t:"Sungrave",s:"Volsung Fá razes Io. Sungrave stands breached and frozen, its shield down."},
  {site:"heraklion",lm:"harbinger",t:"Heraklion",s:"On Europa the Ascomanni fall on Heraklion, and their Harbinger rises from the sea."},
  {site:"nixian",lm:"altar",t:"The Holy Kill",s:"On the acropolis of Zeus, Volsung Fá slays a leviathan hauled out of the Discordia Sea."},
  {site:"thedeep",lm:"trial",t:"The Deep",s:"Beneath the sea, Athena tries Darrow and Diomedes before seven thousand of her people, and Sevro talks her into sparing them."}]};

/* Books II–IV: tours built from the chronicle itself, one stop per event that has a place to stand in */
[2,3,4].forEach(n=>{const titles={2:"Golden Son · a tour of the war",3:"Morning Star · a tour of the Rising",4:"Iron Gold · a tour of the Republic’s war"};const steps=[];
  EVENTS.filter(e=>e.book===n).forEach(e=>{const pl=e.poi&&(POIS[e.body]||[]).find(p=>p.id===e.poi);const site=pl&&pl.site;if(!site)return;steps.push({site,lm:e.lm||null,t:e.title,s:e.text});});
  if(steps.length)TOURS["book"+n]={title:titles[n],steps};});
let T=null,I=0;
const box=document.createElement("div");box.id="tourBox";box.hidden=true;box.innerHTML='<div class="te" id="tourE"></div><div class="tt gild" id="tourT"></div><div class="ts" id="tourS"></div><div class="tb"><button class="btn" id="tourPrev">‹ Back</button><span id="tourN"></span><button class="btn primary" id="tourNext">Next ›</button><button class="btn" id="tourEnd" title="End the tour">✕</button></div>';
document.body.appendChild(box);
function show(){const st=T.steps[I];document.getElementById("tourE").textContent=T.title;document.getElementById("tourT").textContent=st.t;document.getElementById("tourS").textContent=st.s;
  document.getElementById("tourN").textContent=(I+1)+" / "+T.steps.length;document.getElementById("tourPrev").disabled=I===0;document.getElementById("tourNext").textContent=I===T.steps.length-1?"Finish":"Next ›";}
function go(i){I=Math.max(0,Math.min(T.steps.length-1,i));const st=T.steps[I];show();
  const sel=()=>{if(curSite&&curSite.landmarks.find(l=>l.id===st.lm))selectLm(st.lm);};
  if(mode==="site"&&curSiteKey===st.site)sel();else enterSite(st.site,null,sel);}
function start(id){T=TOURS[id];box.hidden=false;document.body.classList.add("touring");go(0);}
function end(){T=null;box.hidden=true;document.body.classList.remove("touring");}
document.getElementById("tourPrev").onclick=()=>go(I-1);
document.getElementById("tourNext").onclick=()=>{if(I>=T.steps.length-1)end();else go(I+1);};
document.getElementById("tourEnd").onclick=end;
addEventListener("keydown",e=>{if(!T||e.target&&/INPUT|TEXTAREA/.test(e.target.tagName))return;if(e.key==="ArrowRight")go(I+1);if(e.key==="ArrowLeft")go(I-1);if(e.key==="Escape")end();});
const b=document.createElement("button");b.className="chronmin";b.id="tourBtn";b.textContent="▶ Tour";b.title="A guided tour of the selected book’s places (Books I, V and VI have tours)";b.onclick=()=>start(typeof bookFilter!=="undefined"&&TOURS["book"+bookFilter]?"book"+bookFilter:"book1");
setInterval(()=>{const k=typeof bookFilter!=="undefined"&&TOURS["book"+bookFilter]?bookFilter:1;const t="▶ Book "+["","I","II","III","IV","V","VI"][k]+" tour";if(b.textContent!==t)b.textContent=t;},1000);
const head=document.querySelector(".chron-head");if(head)head.insertBefore(b,document.getElementById("chronHint"));
window.__tour={start,end,go};
})();

