  const fb=new THREE.Mesh(new THREE.SphereGeometry(1,32,20),new THREE.MeshBasicMaterial({color:col(0xffd8a0),transparent:true,opacity:1,blending:THREE.AdditiveBlending,depthWrite:false}));fb.position.set(0,60,0);root.add(fb);
