  const stem=[];for(let i=0;i<16;i++){const sp=new THREE.Sprite(new THREE.SpriteMaterial({map:GLOW_WHITE,color:col(0xff8a40),transparent:true,opacity:0,depthWrite:false}));root.add(sp);stem.push(sp);}
