        grp.add(D.mesh(SM.metal));const core=new THREE.Mesh(new THREE.SphereGeometry(24,16,12),new THREE.MeshBasicMaterial({color:col(0xff5040)}));core.position.y=246;grp.add(core);
        const glow=glowSprite(glowTexture([[0,"rgba(255,140,120,1)"],[.25,"rgba(255,60,40,.5)"],[1,"rgba(0,0,0,0)"]]),260,.9);glow.position.y=246;grp.add(glow);
        const beam=new THREE.Mesh(new THREE.CylinderGeometry(3,3,1,6,1,true),new THREE.MeshBasicMaterial({color:col(0xff6050),transparent:true,opacity:.5,blending:THREE.AdditiveBlending,depthWrite:false}));grp.add(beam);
        /* beam from the core to the dome above it */
