      C.add(G.cyl(150,230,120,8),TM(0,0,0),0x1c1a1a);for(let i=0;i<40;i++){const a=Math.random()*TAU,r=250+Math.random()*900;C.add(G.box(20+Math.random()*50,8+Math.random()*40,20+Math.random()*40),TM(Math.cos(a)*r,0,Math.sin(a)*r,Math.random()*3,1,1,1,(Math.random()-.5)*.6),0x222020);}
      cr.add(C.mesh(SM.dark));for(let i=0;i<14;i++){const a=Math.random()*TAU,r=Math.random()*1100;const fs=glowSprite(GLOW_WARM,200+Math.random()*200,.8);fs.position.set(Math.cos(a)*r,30,Math.sin(a)*r);fs.userData.fire=true;cr.add(fs);}
