            for(let j=0;j<=Math.round(wz/1.1);j++){const z=-wz/2+j*(wz/Math.round(wz/1.1));add(BOX,TM(xc,h+1.2,z,0,len*1.05,.55,.22,0,-slope),j%3?OB3:EDGE);}
